contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the amount sent to go and which actor sends it.
    // We deploy a Reverter helper that will revert when receiving funds to simulate a failing external callee.
    // The reference contract uses transfer to send remaining balance to owner which always reverts only on OOG
    // and in this scenario should ensure address(c).balance == 0 after go for all inputs. The mutant using call
    // can leave funds in the contract for some inputs when interacting with a reverter-type callee.
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount within reasonable bounds (but wide)
        amount = bound(amount, 0, 1 ether);
        // ensure sender is a different EOA we can fund
        vm.assume(sender != address(this));

        // Deploy a helper that reverts on receive to act as the target callee in C.go
        Reverter rev = new Reverter();

        // Fund the sender
        vm.deal(sender, amount);

        // Call c.go from sender and pass the address of the reverter as the hard-coded target in C
        // In the reference contract, after go returns, address(c).balance should be zero for all inputs.
        vm.prank(sender);
        try c.go{value: amount}() {
            // call succeeded
        } catch {
            // if call reverts, still proceed to assertion reading contract balance
        }

        // Single assertion: reference contract must always have zero balance after go for any admissible input
        assertTrue(address(c).balance == 0);
    }
}

