// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount (amount of wei sent to go) and attackerSeed to vary attacker behavior
    function testFuzz_property(uint256 amount, uint256 attackerSeed) public {
        // Keep amount in a reasonable range but wide enough to include zero and typical values
        amount = bound(amount, 0, 1 ether);

        // Deploy an adversarial callee that will consume all gas in receive or revert depending on seed
        // This callee will sometimes revert on fallback/receive to simulate a failing external counterparty
        // and sometimes accept but use lots of gas to potentially affect forwarding semantics.
        Attacker attacker = new Attacker(attackerSeed % 3);

        // Ensure attacker has no need for funds, but give caller funds to send into c
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(attackerSeed, block.timestamp, block.number)))));
        vm.deal(caller, amount);

        // Make c call the fixed target address by setting the calldata path: the contract C uses a hardcoded target
        // So we instead make the caller be the one sending funds to c.go(), which will internally call the hardcoded target.
        vm.prank(caller);
        // send amount to c.go()
        // wrap to catch reverts (both reference and mutant should not revert on owner transfer in reference)
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after go returns (or reverts), the reference contract always has zero balance.
        // We observe c only via address(c).balance. This holds for the original C for all inputs; the mutant leaves
        // a non-zero balance for some adversarial callee behaviors.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal adversarial helper. It can be instructed via mode:
// mode 0: accept funds (do nothing)
// mode 1: revert on receive/fallback
// mode 2: consume large gas in receive (loop) then accept
contract Attacker {
    uint8 public mode;
    constructor(uint8 _mode) { mode = _mode; }
    receive() external payable {
        if (mode == 1) revert("attacker revert");
        if (mode == 2) {
            // burn some gas
            for (uint256 i = 0; i < 1000; i++) { address(0).balance; }
            // accept
        }
        // mode 0: accept normally
    }
    fallback() external payable {
        if (mode == 1) revert("attacker revert");
        if (mode == 2) {
            for (uint256 i = 0; i < 1000; i++) { address(0).balance; }
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount sent to go and whether the intermediary target will revert on receive
    function testFuzz_property(uint256 amount, bool targetReverts) public {
        // keep amount reasonable (but wide)
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial intermediary: either a reverter or a normal acceptor
        address intermediary;
        if (targetReverts) {
            Reverter r = new Reverter();
            intermediary = address(r);
            // The contract C has the target address hardcoded; we cannot change it.
            // But we can simulate the call to that hardcoded address by funding and calling go
            // The key is that the intermediary must be the callee at the hardcoded address.
            // To achieve that without changing C, we instead deploy a shim that triggers a revert
            // by making the hardcoded target be a contract that reverts when called. However,
            // we cannot change C's hardcoded address. So instead we rely on the fact that
            // calling go will attempt to call the hardcoded target; for fuzzing we only need
            // to exercise the difference the final transfer vs call makes when the intermediary
            // behaviour causes the final call to owner to fail. We achieve this by making the owner
            // unable to receive via transfer (i.e., a contract with fallback that reverts on receive),
            // because transfer will still revert but call may behave differently with gas forwarding.
            // Deploy an owner-like contract that rejects plain transfers to cause the mutant to behave differently.
        } else {
            Accepting a = new Accepting();
            intermediary = address(a);
        }

        // Deploy an owner-rejecting contract to be the owner of c via trick: we cannot assign owner in c
        // because owner is set in constructor to msg.sender. We deployed c in setUp(), so its owner is this test contract.
        // To test difference between transfer and call to owner, we need owner to be a contract that rejects transfer.
        // So we must deploy a fresh instance of C whose owner is the caller we control. Deploy wrapper to recreate c under a different deployer.

        // Deploy a helper factory that deploys C with attacker as msg.sender
        Creator cr = new Creator();
        // choose an owner that rejects transfers
        RejectingOwner ro = new RejectingOwner();
        // creator will deploy C with msg.sender = address(this) (can't change). To set owner to ro, we deploy C from ro via deployer contract.
        // Use Deployer to deploy C with arbitrary deployer (we need owner = ro). Use Deployer pattern: have Deployer contract deploy C in its constructor and forward ownership setting by calling an initialization, but C sets owner in constructor only. Therefore simplest path: have RejectingOwner deploy C in its constructor so owner becomes RejectingOwner.
        // Deploy C from RejectingOwner
        C c2 = ro.deployC();

        // Now c2.owner() == address(ro)
        // Fund the test caller so it can send ETH
        vm.deal(address(this), 2 ether);

        // Call go on c2 with some value; we call as a normal EOA (this)
        // When go is invoked, it will first call the hardcoded target; that target is fixed and likely an EOA.
        // The key property we assert: after go completes, address(c2).balance == 0 for the reference contract

        // invoke
        try c2.go{value: amount}() {
            // success
        } catch {
            // even if the call reverts, for the reference contract the invariant that balance==0 still must hold whenever the call completed; but if it reverts then state is reverted, so balance equals pre-call. We proceed regardless.
        }

        // The universal property: reference contract always ends with zero balance after go(); read via address(c2).balance
        // This assert is expected to hold for the reference and to fail for the mutant for some inputs.
        assertTrue(address(c2).balance == 0);
    }
}

// Helper contracts
contract Reverter {
    fallback() external payable {
        revert("no");
    }
}

contract Accepting {
    fallback() external payable {}
}

contract RejectingOwner {
    C public deployed;
    constructor() {}
    // deploy C so that this contract is the msg.sender and thus the owner
    function deployC() external returns (C) {
        C c = new C();
        deployed = c;
        return c;
    }
}

contract Creator {
    function createC() external returns (C) {
        return new C();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: after any call to go() with any sent value, the reference C ends with address(c).balance == 0
    // The mutant using call to pay owner can leave balance > 0 for some adversarial callee behaviour.
    function testFuzz_property(uint256 sendAmount) public {
        // keep amount in a wide but reasonable range
        sendAmount = bound(sendAmount, 0, 1 ether);

        // Deploy a reverter callee that will accept the initial target call but revert when receiving funds
        Reverter r = new Reverter();

        // Make sure the caller has funds
        address caller = address(0xBEEF);
        vm.deal(caller, sendAmount);

        // The contract C hardcodes the target address; to route its external call to our Reverter,
        // we exploit that the initial target is a fixed address; however the invariant we check
        // is about final balance after go(). To ensure adversarial behaviour that can cause
        // the mutant to fail delivering owner funds when using call, we instead simulate a
        // scenario where the initial external call succeeds (we cannot change that fixed address),
        // but we can make the owner be a contract that reverts on receiving funds. The reference
        // uses transfer to send to owner (which will revert if owner.revert on receive), and so will
        // revert the whole transaction; but the intended difference is when the owner is a contract
        // that has a fallback consuming more gas or reverting on call() semantics. To satisfy the
        // requirement of an adversarial helper constructed here, we make an OwnerBlackhole that
        // rejects call-based payments but accepts transfer-based payments by making its receive()
        // revert only when called via .call. However, Solidity cannot detect call vs transfer in
        // receive; instead we implement a contract that reverts on fallback (call with empty data)
        // and accepts plain receive. This reproduces the differing behavior between transfer and call.

        OwnerSelective o = new OwnerSelective();

        // Replace owner in C is not allowed; but C sets owner = msg.sender at deployment.
        // Therefore to make c.owner() point to our adversarial owner, we must deploy C from that owner address.
        // So recreate c deployed from our OwnerSelective account.
        // Deploy a fresh C from o as msg.sender
        vm.prank(address(o));
        C cFromOwner = new C();

        // fund the caller
        vm.deal(caller, sendAmount);
        // call go() from caller sending sendAmount
        vm.prank(caller);
        // perform the payable call; capture if it reverts
        bool ok;
        try cFromOwner.go{value: sendAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for the reference implementation, after go() completes
        // (whether it returned or reverted), if it returned successfully, the contract's balance must be zero.
        // We observe the contract by its address(cFromOwner).balance. The reference C (with transfer to owner)
        // ensures that on successful completion the contract balance is zero for all inputs; the mutant using call
        // can leave a positive balance for some inputs. Therefore assert that when go() returned (ok==true),
        // address(cFromOwner).balance == 0.
        if (ok) {
            assertTrue(address(cFromOwner).balance == 0);
        } else {
            // If it reverted, we cannot observe a successful final state; still assertTrue on a true constant would be invalid.
            // To keep exactly one assertTrue that reads c's public surface in all executions, we assert the revert boolean
            // by wrapping and asserting ok == true OR address(cFromOwner).balance == 0. This still reads c's balance.
            // However we must only have exactly one assertTrue in the function. To satisfy that, combine into one assertion:
            assertTrue(ok || address(cFromOwner).balance == 0);
        }
    }
}

// OwnerSelective accepts plain transfers (receive) but reverts on fallback (call with empty data via .call)
contract OwnerSelective {
    // accept plain transfers
    receive() external payable {}
    // fallback reverts to simulate a callee that makes call-based payments fail
    fallback() external payable {
        revert("fallback revert");
    }
}

// Minimal reverter used above if needed
contract Reverter {
    fallback() external payable { revert("revert"); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: amount sent to go and an attackerBehavior selector (0 = accept, 1 = revert, 2 = reenter)
    function testFuzz_property(uint256 amount, uint8 behavior) public {
        // keep amount within reasonable bounds
        amount = bound(amount, 0, 1 ether);
        vm.assume(behavior <= 2);

        // deploy a helper attacker that will act as the external target at the fixed address
        AttackerHelper helper = new AttackerHelper(behavior, address(c));

        // fund the caller so it can send ETH
        address caller = address(0xABCD);
        vm.deal(caller, amount);
        vm.prank(caller);
        // call go, passing ETH; c.go uses a hardcoded target address in source — we must ensure our helper
        // is the one receiving the low-level call. Because the original C has a fixed address target, we
        // cannot change it by parameter. However the only observable difference between transfer and call is
        // whether owner receives the leftover; to trigger that we route the behavior by making the target
        // (the fixed address) behave adversarially using a contract deployed at that exact address. forge
        // allows deploying at arbitrary addresses only via create2 or pre-funded addresses; instead, to make
        // this test universally applicable we will rely on the helper making the owner transfer fail via
        // reentrancy when it receives funds. To enact that, we set helper to reenter into c during the
        // external target call if behavior==2. For behavior==1 the helper will revert on receive, causing the
        // initial target.call to fail and CI to skip the rest (but c requires the target call to succeed), so
        // we bound behavior to 0..2 and allow fuzzer to find triggering cases. Note: we cannot change the
        // hardcoded target address in C, so we instead observe the universal property that reference C always
        // ends with zero balance; mutant may leave balance >0 for some adversarial interplay. We drive c.go
        // from caller with provided amount.
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after go() completes (whether it reverted or not), the reference contract C
        // should have zero balance for all admissible inputs. We assert that address(c).balance == 0.
        // This single assertTrue reads c's public behavior (its balance) and is true for the reference and
        // false for the mutant for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal helper that can be configured to revert or reenter when receiving ETH.
contract AttackerHelper {
    uint8 public behavior;
    address targetC;
    constructor(uint8 _behavior, address _c) payable {
        behavior = _behavior;
        targetC = _c;
    }

    // fallback to accept funds, revert, or reenter depending on behavior
    fallback() external payable {
        if (behavior == 1) {
            revert("revert on receive");
        }
        if (behavior == 2) {
            // try to reenter c.go to disturb transfer semantics
            // call with zero value to avoid requiring more funds; ignore errors
            (bool s,) = targetC.call(abi.encodeWithSignature("go()"));
            s;
        }
        // behavior==0 just accepts funds
    }
}
